<script setup>
import { computed,ref,watch } from 'vue'
const props=defineProps({draft:{type:Object,required:true},fields:{type:Array,default:()=>[]},direct:{type:Boolean,default:false}})
const advanced=ref(false),descriptionParts=ref([])
const commonKeys=['product_name','name','title','price','description','buy_link','url','id','value','code','label']
const fieldOptions=computed(()=>{const seen=new Set(),out=[];for(const key of commonKeys){if(!seen.has(key)){seen.add(key);out.push(key)}}for(const key of [props.draft.dynamic_title_path,props.draft.dynamic_value_path])if(key&&!seen.has(key)){seen.add(key);out.push(key)}return out})
function syncSource(){const f=props.fields.find(x=>String(x.id)===String(props.draft.dynamic_source_field_id));props.draft.dynamic_source_field_key=f?.key||''}
function syncTarget(){const f=props.fields.find(x=>String(x.id)===String(props.draft.dynamic_save_field_id));props.draft.dynamic_save_field_key=f?.key||''}
function parseDescription(value){const text=String(value||''),parts=[],re=/\{\{\s*item\.([^}]+?)\s*\}\}/g;let last=0,m;while((m=re.exec(text))){if(m.index>last)parts.push({type:'text',value:text.slice(last,m.index)});parts.push({type:'field',value:m[1].trim()});last=re.lastIndex}if(last<text.length)parts.push({type:'text',value:text.slice(last)});return parts}
function buildDescription(){props.draft.dynamic_description=descriptionParts.value.map(p=>p.type==='field'?`{{item.${p.value}}}`:p.value).join('')}
function addDescriptionField(){descriptionParts.value.push({type:'field',value:'description'});buildDescription()}function addDescriptionText(){descriptionParts.value.push({type:'text',value:' - '});buildDescription()}function removePart(i){descriptionParts.value.splice(i,1);buildDescription()}
watch(()=>props.draft.dynamic_description,v=>{const built=descriptionParts.value.map(p=>p.type==='field'?`{{item.${p.value}}}`:p.value).join('');if(String(v||'')!==built)descriptionParts.value=parseDescription(v)},{immediate:true})
</script>
<template><section class="dynamic-list"><div class="intro"><strong>List Content</strong><p>Choose where the choices come from and how each option should look.</p></div>
<div class="field"><div class="field-label">Content source</div><select v-model="draft.row_generation"><option value="static">Static choices from connected blocks</option><option value="dynamic">Dynamic choices from API / JSON</option></select></div>
<template v-if="draft.row_generation==='dynamic'">
<div class="section-title"><span>1</span><div><strong>Data source</strong><small>Select the custom field containing your API response or JSON list.</small></div></div>
<div class="field"><div class="field-label">JSON data</div><select v-model="draft.dynamic_source_field_id" @change="syncSource"><option value="">— Select data source —</option><option v-for="f in fields" :key="f.id" :value="f.id">{{f.label||f.name||f.key}} · %{{f.key}}%</option></select></div>
<div class="section-title"><span>2</span><div><strong>List row</strong><small>Choose what the subscriber sees and what value is returned when they select it.</small></div></div>
<div class="field"><div class="field-label">Title</div><select v-model="draft.dynamic_title_path"><option value="">— Select JSON field —</option><option v-for="key in fieldOptions" :key="key" :value="key">{{key}}</option></select><div class="help">The main label shown for each option.</div></div>
<div class="field"><div class="field-label">Description <span>Optional</span></div><div class="help top-help">Build the subtitle from JSON fields and plain text.</div><div class="parts" v-if="descriptionParts.length"><div v-for="(part,i) in descriptionParts" :key="i" class="part"><span :class="['badge',part.type==='text'?'text':'']">{{part.type==='field'?'FIELD':'TEXT'}}</span><select v-if="part.type==='field'" v-model="part.value" @change="buildDescription"><option v-for="key in fieldOptions" :key="key" :value="key">{{key}}</option></select><input v-else v-model="part.value" @input="buildDescription" placeholder="Text between fields"><button type="button" @click="removePart(i)">×</button></div></div><div class="part-actions"><button type="button" @click="addDescriptionField">＋ Add field</button><button type="button" @click="addDescriptionText">＋ Add text</button></div></div>
<div class="field"><div class="field-label">Value when selected</div><select v-model="draft.dynamic_value_path"><option value="">— Same as title —</option><option v-for="key in fieldOptions" :key="key" :value="key">{{key}}</option></select><div class="help">The value stored when the subscriber chooses this row.</div></div>
<div class="section-title"><span>3</span><div><strong>After selection</strong><small>Choose where WA Connect should store the selected value.</small></div></div>
<div class="field"><div class="field-label">Save selected value to</div><select v-model="draft.dynamic_save_field_id" @change="syncTarget"><option value="">— Do not save —</option><option v-for="f in fields" :key="f.id" :value="f.id">{{f.label||f.name||f.key}} · %{{f.key}}%</option></select></div>
<label class="check"><input v-model="draft.dynamic_save_entire_object" type="checkbox"><span>Save the entire selected item instead of only the selected value</span></label>
<button class="advanced-toggle" type="button" @click="advanced=!advanced">{{advanced?'▾':'▸'}} Advanced options</button><div v-if="advanced" class="advanced"><div class="field"><div class="field-label">Array path</div><input v-model="draft.dynamic_array_path" placeholder="Leave blank for entire response"><div class="help">Only needed when the list is nested, e.g. <code>data.products</code>.</div></div><div class="field"><div class="field-label">Raw description template</div><input v-model="draft.dynamic_description" placeholder="{{item.price}} - {{item.description}}"><div class="help">Advanced template syntax. The visual description builder above updates this automatically.</div></div><div class="keys"><b>Field keys</b><span>Title: <code>{{draft.dynamic_title_path||'—'}}</code></span><span>Value: <code>{{draft.dynamic_value_path||draft.dynamic_title_path||'—'}}</code></span><span v-if="draft.dynamic_source_field_key">Source: <code>%{{draft.dynamic_source_field_key}}%</code></span><span v-if="draft.dynamic_save_field_key">Save to: <code>%{{draft.dynamic_save_field_key}}%</code></span></div></div>
<div class="preview"><b>Row preview</b><strong>{{draft.dynamic_title_path?`{ ${draft.dynamic_title_path} }`:'Choose a title field'}}</strong><span v-if="draft.dynamic_description">{{draft.dynamic_description.replace(/\{\{\s*item\.([^}]+?)\s*\}\}/g,'{ $1 }')}}</span><small>Selected value → {{draft.dynamic_save_entire_object?'Entire item':(draft.dynamic_value_path||draft.dynamic_title_path||'not configured')}}</small></div></template></section></template>
<style scoped>
.dynamic-list{border:1px solid #dbe7e2;border-radius:12px;padding:14px;margin:14px 0;background:#f9fcfb}.intro{margin-bottom:15px}.intro strong{font-size:15px}.intro p{font-size:12px;color:#6b7d76;margin:4px 0 0;line-height:1.4}.field{display:block;margin:12px 0}.field-label{display:block;font-size:12px;font-weight:750;color:#213a30;margin:0 0 6px}.field-label span{font-size:10px;font-weight:500;color:#84938c;margin-left:4px}.field select,.field input{display:block;width:100%;height:40px;box-sizing:border-box;border:1px solid #cbd9d2;border-radius:8px;background:#fff;color:#1d3028;padding:0 34px 0 11px;font-size:13px;line-height:40px;box-shadow:0 1px 1px rgba(20,50,38,.03)}.field select{appearance:auto}.field input{padding-right:11px}.field select:focus,.field input:focus,.part select:focus,.part input:focus{outline:none;border-color:#56aa7e;box-shadow:0 0 0 3px rgba(22,143,85,.09)}.help{display:block;font-size:11px;font-weight:400;color:#788981;line-height:1.4;margin-top:5px}.top-help{margin-top:-2px;margin-bottom:8px}.section-title{display:flex;gap:9px;align-items:flex-start;margin:20px 0 10px;padding-top:15px;border-top:1px solid #e3ece8}.section-title>span{display:grid;place-items:center;width:23px;height:23px;border-radius:50%;background:#168f55;color:white;font-size:11px;font-weight:800;flex:0 0 auto}.section-title strong{display:block;font-size:14px;color:#19392b}.section-title small{display:block;font-size:11px;font-weight:400;color:#71817b;line-height:1.35;margin-top:2px}.parts{display:flex;flex-direction:column;gap:7px}.part{display:grid;grid-template-columns:48px minmax(0,1fr) 32px;gap:6px;align-items:center}.part select,.part input{width:100%;min-width:0;height:38px;box-sizing:border-box;border:1px solid #cbd9d2;border-radius:8px;background:#fff;padding:0 10px;font-size:12px;color:#1d3028}.part button{height:38px;border:0;border-radius:8px;background:#fff0f0;color:#b33;font-size:16px;cursor:pointer}.badge{font-size:8px;font-weight:800;color:#17764a;background:#e5f7ed;padding:6px 4px;border-radius:6px;text-align:center}.badge.text{color:#5f6e67;background:#edf1ef}.part-actions{display:flex;gap:7px;margin:9px 0 0}.part-actions button,.advanced-toggle{border:1px solid #b9d9ca;background:#fff;border-radius:8px;padding:8px 10px;color:#176b46;font-weight:700;cursor:pointer}.check{display:grid!important;grid-template-columns:18px 1fr;gap:7px;align-items:start!important;margin:11px 0 15px!important;font-size:11px!important;font-weight:500!important;line-height:1.35;color:#52665c}.check input{width:15px!important;height:15px!important;margin:1px 0 0!important}.advanced-toggle{width:100%;text-align:left}.advanced{margin-top:8px;padding:10px;background:#f1f6f4;border-radius:8px}.keys{font-size:11px;display:flex;flex-direction:column;gap:3px;margin-top:9px}.preview{margin-top:12px;background:#eef8f3;border-radius:8px;padding:11px;display:flex;flex-direction:column;gap:4px}.preview>b{font-size:10px;text-transform:uppercase;color:#5d786a}.preview>strong{font-size:13px}.preview>span,.preview>small{font-size:11px;color:#687c72}
</style>